() => {
  const sec = document.getElementById('pricing');
  sec.scrollIntoView();
  const cards = sec.querySelectorAll('.grid > div');
  const pro = cards[1];
  const free = cards[0];
  const cs = getComputedStyle(pro);
  const grid = getComputedStyle(sec.querySelector('.grid'));
  const btn = getComputedStyle(pro.querySelector('a'));
  return {
    cardCount: cards.length,
    gridColumns: grid.gridTemplateColumns,
    proBorderColor: cs.borderColor,
    proBorderWidth: cs.borderTopWidth,
    proBoxShadow: cs.boxShadow.slice(0,40),
    proBtnBg: btn.backgroundColor,
    freeBtnBg: getComputedStyle(free.querySelector('a')).backgroundColor,
    freePadding: getComputedStyle(free).padding
  };
}

