() => {
  const sec = document.getElementById('pricing');
  const cards = sec.querySelectorAll('.grid > div');
  const free = cards[0], pro = cards[1];
  // gather all css rules text
  let all = '';
  for (const ss of document.styleSheets) {
    try { for (const r of ss.cssRules) all += r.cssText + '\n'; } catch(e){}
  }
  const has = (sel) => all.includes(sel);
  return {
    freeBorderWidth: getComputedStyle(free).borderTopWidth,
    freeBoxShadow: getComputedStyle(free).boxShadow.slice(0,30),
    hasBorder2: has('.border-2'),
    hasBorder: has('.border '),
    hasShadowXl: has('.shadow-xl'),
    hasShadowSm: has('.shadow-sm'),
    hasScale: all.includes('scale-')
  };
}

